INSERT INTO api_catalog (name, description, category, base_url, auth_type, auth_config, rate_limit, is_active, docs_url, endpoints, tags, api_version, cors_supported, requires_proxy, credit_required, cache_ttl_seconds, deprecated_at) VALUES (
  'Countries (Self-hosted)', '250개 나라의 수도, 지역, 국기, 언어, 통화, 국가번호, 면적 정보를 제공해요. REST Countries 대체 API로, 가입·키 없이 바로 사용할 수 있어요.', 'data', 'https://xzawed.xyz', 'none', NULL, NULL, true, NULL, '[{"path": "/api/v1/countries", "method": "GET", "parameters": {"region": "string", "search": "string"}, "description": "전체 나라 목록 (region·search 쿼리로 필터 가능)"}, {"path": "/api/v1/countries/KR", "method": "GET", "parameters": {"code": "string"}, "description": "국가 코드(cca2/cca3)로 단건 조회. 경로의 KR을 원하는 코드로 바꾸세요 (예: KOR, US, JP)"}]'::jsonb, ARRAY['data','countries','geography','free','no-auth'], 'v1', true, false, NULL, 86400, NULL);

