INSERT INTO api_catalog (name, description, category, base_url, auth_type, auth_config, rate_limit, is_active, docs_url, endpoints, tags, api_version, cors_supported, requires_proxy, credit_required, cache_ttl_seconds, deprecated_at) VALUES (
  'JSONPlaceholder', '가짜 게시글, 댓글, 할일 목록, 사진 앨범 데이터. 연습용 또는 프로토타입 만들 때 유용해요.', 'data', 'https://jsonplaceholder.typicode.com', 'none', NULL, '500', true, 'https://jsonplaceholder.typicode.com/guide/', E'[{"path": "/posts", "method": "GET", "description": "게시글 목록", "exampleCall": "const res = await fetch(''/api/v1/proxy?apiId=04e79764-c27c-46d8-b63c-2794fbe5a3f7&proxyPath=%2Fposts'');\\nconst items = await res.json(); // [{id, userId, title, body}]"}, {"path": "/todos", "method": "GET", "description": "할일 목록", "exampleCall": "const res = await fetch(''/api/v1/proxy?apiId=04e79764-c27c-46d8-b63c-2794fbe5a3f7&proxyPath=%2Ftodos'');\\nconst items = await res.json(); // [{id, userId, title, completed}]"}, {"path": "/users", "method": "GET", "description": "사용자 목록", "exampleCall": "const res = await fetch(''/api/v1/proxy?apiId=04e79764-c27c-46d8-b63c-2794fbe5a3f7&proxyPath=%2Fusers'');\\nconst items = await res.json(); // [{id, name, username, email}]"}]'::jsonb, ARRAY['data','mock','placeholder','free','no-auth'], 'v1', true, false, NULL, NULL, NULL);

