-- PokéAPI  [entertainment, active=true]
INSERT INTO api_catalog (name, description, category, base_url, auth_type, auth_config, rate_limit, is_active, docs_url, endpoints, tags, api_version, cors_supported, requires_proxy, credit_required, cache_ttl_seconds, deprecated_at) VALUES (
  'PokéAPI', '포켓몬 도감. 1,000마리 이상 포켓몬의 능력치, 타입, 이미지를 확인할 수 있어요.', 'entertainment', 'https://pokeapi.co', 'none', NULL, '300', true, 'https://pokeapi.co/docs/v2', E'[{"path": "/api/v2/pokemon/{id_or_name}", "method": "GET", "parameters": {"id_or_name": "string"}, "description": "포켓몬 상세 정보"}, {"path": "/api/v2/pokemon", "method": "GET", "parameters": {"limit": "number", "offset": "number"}, "description": "포켓몬 목록", "exampleCall": "const res = await fetch(''/api/v1/proxy?apiId=02cea7ab-d89a-4e51-b9c5-32ed0fd00338&proxyPath=%2Fapi%2Fv2%2Fpokemon'');\\nconst data = await res.json();\\nconst items = data.results; // [{name, url}]", "responseDataPath": "results"}]'::jsonb, ARRAY['entertainment','pokemon','games','free','no-auth'], 'v2', true, false, NULL, NULL, NULL);

-- TheMealDB  [entertainment, active=true]
INSERT INTO api_catalog (name, description, category, base_url, auth_type, auth_config, rate_limit, is_active, docs_url, endpoints, tags, api_version, cors_supported, requires_proxy, credit_required, cache_ttl_seconds, deprecated_at) VALUES (
  'TheMealDB', '전세계 레시피 데이터베이스. 랜덤 레시피, 검색, 카테고리별 필터 제공. ⚠️ 무료 키(v1/1)는 100건 이하·단일 재료 필터·기본 기능만 지원. v2 기능(랜덤 10개 등)은 Patreon 구독 키 필요.', 'entertainment', 'https://www.themealdb.com/api/json/v1/1', 'none', NULL, NULL, true, 'https://www.themealdb.com/api.php', E'[{"path": "/random.php", "method": "GET", "description": "랜덤 레시피 1개", "exampleCall": "const res = await fetch(''/api/v1/proxy?apiId=<이 API ID>&proxyPath=%2Frandom.php'');\\nconst data = await res.json();\\nconst meal = data.meals[0]; // {strMeal, strCategory, strInstructions, strMealThumb}", "responseDataPath": "meals[0]"}, {"path": "/search.php", "method": "GET", "parameters": {"s": "요리명 (예: chicken)"}, "description": "레시피 검색", "responseDataPath": "meals"}, {"path": "/filter.php", "method": "GET", "parameters": {"c": "Chicken | Beef | Seafood | Vegetarian 등"}, "description": "카테고리별 레시피", "responseDataPath": "meals"}]'::jsonb, ARRAY['fun','food','recipe','cooking','free','no-auth'], NULL, true, false, NULL, NULL, NULL);

-- KOPIS 공연예술  [entertainment, active=false]
INSERT INTO api_catalog (name, description, category, base_url, auth_type, auth_config, rate_limit, is_active, docs_url, endpoints, tags, api_version, cors_supported, requires_proxy, credit_required, cache_ttl_seconds, deprecated_at) VALUES (
  'KOPIS 공연예술', '공연예술통합전산망(KOPIS) 공연 정보. 공연 목록·상세·공연장 조회. XML 응답 (DOMParser 파싱 필요). (KOPIS 키 필요)', 'entertainment', 'https://www.kopis.or.kr/openApi/restful', 'api_key', '{"env_var": "API_KEY_KOPIS", "param_in": "query", "param_name": "service"}'::jsonb, '100', false, 'https://www.kopis.or.kr/por/cs/openapi/openApiUsageGuide.do', E'[{"path": "/pblprfr", "method": "GET", "parameters": {"rows": "10", "cpage": "1", "shcaf": "공연시설코드 (선택)", "shcat": "공연분야코드 (선택)", "eddate": "종료일 YYYYMMDD", "stdate": "시작일 YYYYMMDD", "shprfnm": "공연명 검색 (선택)"}, "description": "공연 목록 조회 (XML 반환)", "exampleCall": "const res = await fetch(''/api/v1/proxy?apiId=<이 API ID>&proxyPath=%2Fpblprfr&stdate=20250501&eddate=20250531&cpage=1&rows=10'');\\nconst xml = await res.text();\\nconst parser = new DOMParser();\\nconst doc = parser.parseFromString(xml, ''text/xml'');\\nconst items = doc.querySelectorAll(''db'');", "responseDataPath": ""}, {"path": "/pblprfr/{mt20id}", "method": "GET", "parameters": {"mt20id": "공연 ID"}, "description": "공연 상세 정보 (XML 반환)", "responseDataPath": ""}]'::jsonb, ARRAY['entertainment','performance','culture','theater','kr','api_key','xml'], NULL, false, true, NULL, NULL, NULL);

