  'RAWG', '500,000개 이상 게임 데이터베이스. 인기 게임 목록, 검색, 상세정보 제공.', 'entertainment', 'https://api.rawg.io/api', 'api_key', '{"env_var": "API_KEY_RAWG", "param_in": "query", "param_name": "key"}'::jsonb, '20000/월', false, 'https://api.rawg.io/docs', E'[{"path": "/games", "method": "GET", "parameters": {"genres": "string (예: action,rpg)", "ordering": "-rating", "page_size": "20"}, "description": "게임 목록 조회", "exampleCall": "const res = await fetch(''/api/v1/proxy?apiId=<이 API ID>&proxyPath=%2Fgames&page_size=20&ordering=-rating'');\\nconst data = await res.json();\\nconst games = data.results; // [{name, rating, background_image, genres}]", "responseDataPath": "results"}, {"path": "/games/{id}", "method": "GET", "parameters": {"id": "게임 ID 또는 slug"}, "description": "게임 상세 정보", "responseDataPath": ""}, {"path": "/genres", "method": "GET", "description": "장르 목록", "responseDataPath": "results"}]'::jsonb, ARRAY['entertainment','games','gaming','api_key'], NULL, true, false, NULL, NULL, NULL);

