  'JokeAPI', '카테고리별 랜덤 유머. 프로그래밍 개그, 아재 개그 등 분위기 전환에 딱이에요.', 'fun', 'https://v2.jokeapi.dev', 'none', NULL, '120', true, 'https://jokeapi.dev/', '[{"path": "/joke/{category}", "method": "GET", "parameters": {"lang": "string", "type": "string", "category": "string"}, "description": "카테고리별 랜덤 유머 조회"}]'::jsonb, ARRAY['entertainment','jokes','humor','free','no-auth'], 'v2', true, false, NULL, NULL, NULL);

-- ZenQuotes  [fun, active=true]
INSERT INTO api_catalog (name, description, category, base_url, auth_type, auth_config, rate_limit, is_active, docs_url, endpoints, tags, api_version, cors_supported, requires_proxy, credit_required, cache_ttl_seconds, deprecated_at) VALUES (
  'ZenQuotes', '명언·격언 랜덤 표시. 오늘의 한마디, 동기부여 화면을 만들 때 좋아요. HTTPS 지원, 무료, 인증 불필요.', 'fun', 'https://zenquotes.io/api', 'none', NULL, NULL, true, 'https://docs.zenquotes.io', E'[{"path": "/random", "method": "GET", "description": "랜덤 명언 1개 조회", "exampleCall": "const res = await fetch(''/api/v1/proxy?apiId=4c6f5228-e6ec-45bb-b0bb-e947dcdeb1c1&proxyPath=%2Frandom'');\\nconst data = await res.json();\\nconst quote = data[0];\\n// quote.q (명언), quote.a (저자)", "responseDataPath": "[0]"}, {"path": "/quotes", "method": "GET", "description": "명언 50개 조회", "exampleCall": "const res = await fetch(''/api/v1/proxy?apiId=4c6f5228-e6ec-45bb-b0bb-e947dcdeb1c1&proxyPath=%2Fquotes'');\\nconst data = await res.json();\\n// data: [{q: ''명언'', a: ''저자''}, ...]", "responseDataPath": ""}]'::jsonb, ARRAY['fun','quotes','inspiration','free','no-auth','https'], NULL, false, true, NULL, NULL, NULL);

-- HIRA 병원정보  [health, active=false]
INSERT INTO api_catalog (name, description, category, base_url, auth_type, auth_config, rate_limit, is_active, docs_url, endpoints, tags, api_version, cors_supported, requires_proxy, credit_required, cache_ttl_seconds, deprecated_at) VALUES (
  'HIRA 병원정보', '건강보험심사평가원 병원·의원 정보 조회. 주소·진료과로 병원 검색. (공공데이터포털 키 필요)', 'health', 'https://apis.data.go.kr/B551182/hospInfoServicev2', 'api_key', '{"env_var": "API_KEY_HIRA", "param_in": "query", "param_name": "serviceKey"}'::jsonb, '300', false, 'https://www.data.go.kr/data/15001698/openapi.do', E'[{"path": "/getHospBasisList", "method": "GET", "parameters": {"addr": "주소 (예: 서울특별시 강남구)", "type": "json", "pageNo": "1", "dgsbjtCd": "진료과코드 (예: 01=내과, 11=정형외과)", "numOfRows": "10"}, "description": "병원 기본 정보 목록", "exampleCall": "const res = await fetch(''/api/v1/proxy?apiId=<이 API ID>&proxyPath=%2FgetHospBasisList&addr=서울특별시&pageNo=1&numOfRows=5&type=json'');\\nconst data = await res.json();\\nconst hospitals = data.response.body.items.item; // [{yadmNm, addr, telno, clCdNm}]", "responseDataPath": "response.body.items.item"}]'::jsonb, ARRAY['health','hospital','medical','kr','api_key','data.go.kr'], NULL, false, true, NULL, NULL, NULL);

