  'Hacker News API', 'IT·스타트업 뉴스 실시간 조회. 실리콘밸리에서 가장 핫한 기술 소식을 모아볼 수 있어요.', 'news', 'https://hacker-news.firebaseio.com', 'none', NULL, '500', true, 'https://github.com/HackerNews/API', E'[{"path": "/v0/topstories.json", "method": "GET", "description": "인기 뉴스 ID 목록 (최대 500개)", "exampleCall": "const res = await fetch(''/api/v1/proxy?apiId=de8f5375-22dc-4573-9a64-2903c150fece&proxyPath=%2Fv0%2Ftopstories.json'');\\nconst storyIds = await res.json(); // [integer IDs]"}, {"path": "/v0/item/{id}.json", "method": "GET", "parameters": {"id": "number"}, "description": "뉴스 상세 조회"}]'::jsonb, ARRAY['news','tech','hacker-news','free','no-auth'], 'v0', true, false, NULL, NULL, NULL);

