  'The Color API', 'HEX/RGB 색상 코드로 색상 이름·보완색·팔레트 생성. 인증 불필요.', 'utility', 'https://www.thecolorapi.com', 'none', NULL, NULL, true, 'https://www.thecolorapi.com/docs', E'[{"path": "/id", "method": "GET", "parameters": {"hex": "HEX 코드 (# 제외, 예: FF5733)"}, "description": "색상 정보 조회 (이름, RGB, HSL)", "exampleCall": "const res = await fetch(''/api/v1/proxy?apiId=<이 API ID>&proxyPath=%2Fid&hex=FF5733'');\\nconst data = await res.json();\\n// data.name.value, data.rgb, data.hsl, data.image.bare", "responseDataPath": ""}, {"path": "/scheme", "method": "GET", "parameters": {"hex": "string", "mode": "monochrome | analogic | complement | triad | quad", "count": "5"}, "description": "색상 팔레트 생성", "responseDataPath": "colors"}]'::jsonb, ARRAY['utility','color','design','palette','free','no-auth'], NULL, true, false, NULL, NULL, NULL);

