  'Open-Meteo', '무료 날씨 API. 키 불필요, 비상업적 전용(CC BY 4.0). 위도/경도 기반 현재 날씨 및 예보 제공.', 'weather', 'https://api.open-meteo.com', 'none', NULL, '10000/일', true, 'https://open-meteo.com/en/docs', '[{"path": "/v1/forecast", "method": "GET", "description": "위도/경도 기반 날씨 예보", "example_call": "/v1/forecast?latitude=37.5665&longitude=126.9780&current_weather=true"}]'::jsonb, ARRAY['weather','forecast','free','no-key'], NULL, true, false, NULL, NULL, NULL);

