-- ============================================================
-- 폐기 API 후속(successor) 연결
-- ============================================================
-- successor_id는 생성된 UUID이므로 이름 기준으로 연결한다.
-- REST Countries(폐기) → Countries (Self-hosted) 대체.
UPDATE api_catalog
SET successor_id = (SELECT id FROM api_catalog WHERE name = 'Countries (Self-hosted)')
WHERE name = 'REST Countries';
